enum class CardioLogField {
    DURATION,
    DISTANCE,
    AVG_PACE,
    AVG_SPEED,
    ELEVATION_GAIN,
    AVG_HEART_RATE,
    MAX_HEART_RATE,
    AVG_CADENCE,
    AVG_POWER,
    CALORIES,
    EFFORT,
    NOTE,
}

private val HEART_TO_NOTE =
    listOf(
        CardioLogField.AVG_HEART_RATE,
        CardioLogField.MAX_HEART_RATE,
        CardioLogField.AVG_CADENCE,
        CardioLogField.CALORIES,
        CardioLogField.EFFORT,
        CardioLogField.NOTE,
    )

