            CardioActivity.INDOOR_RIDE -> {
                logFieldsOf(CardioActivity.OUTDOOR_RIDE) - ELEVATION_GAIN
            }

            CardioActivity.ELLIPTICAL -> {
                listOf(DURATION, DISTANCE) + HEART_TO_NOTE
            }

            CardioActivity.ROWER -> {
                listOf(DURATION, DISTANCE, AVG_PACE, AVG_POWER) + HEART_TO_NOTE
            }
        }
    }
